{"content":"const NUMERALS = [
  [1000, 'M'],
  [900, 'CM'],
  [500, 'D'],
  [400, 'CD'],
  [100, 'C'],
  [90, 'XC'],
  [50, 'L'],
  [40, 'XL'],
  [10, 'X'],
  [9, 'IX'],
  [5, 'V'],
  [4, 'IV'],
  [1, 'I'],
];

/**
 * Convert an integer from 1 through 3999 to a canonical Roman numeral.
 * @param {number} n
 * @returns {string}
 * @throws {RangeError} If n is not an integer in the supported range.
 */
export function toRoman(n) {
  if (!Number.isInteger(n) || n < 1 || n > 3999) {
    throw new RangeError('Expected an integer from 1 through 3999');
  }

  let result = '';
  let remaining = n;
  for (const [value, numeral] of NUMERALS) {
    while (remaining >= value) {
      result += numeral;
      remaining -= value;
    }
  }
  return result;
}
