{"content":"import assert from 'node:assert/strict';
import test from 'node:test';
import { toRoman } from '../src/roman.js';

test('converts boundaries, base symbols, and subtractive pairs', () => {
  const examples = [
    [1, 'I'], [3, 'III'], [4, 'IV'], [5, 'V'], [9, 'IX'],
    [10, 'X'], [40, 'XL'], [50, 'L'], [90, 'XC'],
    [100, 'C'], [400, 'CD'], [500, 'D'], [900, 'CM'],
    [1000, 'M'], [3999, 'MMMCMXCIX'],
  ];
  for (const [input, expected] of examples) {
    assert.equal(toRoman(input), expected, `input: ${input}`);
  }
});

test('converts mixed numerals using canonical notation', () => {
  const examples = [
    [27, 'XXVII'], [49, 'XLIX'], [99, 'XCIX'], [444, 'CDXLIV'],
    [944, 'CMXLIV'], [1453, 'MCDLIII'], [1994, 'MCMXCIV'],
    [2024, 'MMXXIV'], [3888, 'MMMDCCCLXXXVIII'],
  ];
  for (const [input, expected] of examples) {
    assert.equal(toRoman(input), expected, `input: ${input}`);
  }
});

test('rejects out-of-range, fractional, and non-number inputs', () => {
  const invalid = [
    -1, -1000, 0, -0, 4000, 10000, Number.MAX_SAFE_INTEGER,
    0.5, 1.5, 3999.5, NaN, Infinity, -Infinity,
    '1', '', null, undefined, true, false, {}, [], [1], 1n, Symbol('1'),
  ];
  for (const input of invalid) {
    assert.throws(() => toRoman(input), RangeError, `input: ${String(input)}`);
  }
  assert.throws(() => toRoman(), RangeError);
});

test('every supported integer produces a canonical numeral with the correct value', () => {
  const canonical = /^M{0,3}(CM|CD|D?C{0,3})(XC|XL|L?X{0,3})(IX|IV|V?I{0,3})$/;
  const values = { I: 1, V: 5, X: 10, L: 50, C: 100, D: 500, M: 1000 };

  for (let n = 1; n <= 3999; n++) {
    const roman = toRoman(n);
    assert.notEqual(roman, '', `input: ${n}`);
    assert.match(roman, canonical, `input: ${n}`);

    let decoded = 0;
    for (let i = 0; i < roman.length; i++) {
      const current = values[roman[i]];
      const next = values[roman[i + 1]] ?? 0;
      decoded += current < next ? -current : current;
    }
    assert.equal(decoded, n, `numeral: ${roman}`);
  }
});
